function renderPanel(){if(!panel)return;({bag:showBag,craft:showCraft,storage:showStorage,friends:showFriends,profile:showProfile,goals:showGoals,map:showMap,conditions:showConditions,guest:showGuest,activity:showActivity,object:showObject,tool:showTool,gate:showGate})[panel]?.()}
function showBag(){let rows=Object.entries(state.inventory).map(([k,v])=>`<div>${NAMES[k]}<b>${v}</b></div>`).join(''),level=happinessLevel(),next=HAPPINESS_THRESHOLDS[level],abilities=[state.tools.axe&&'숲 채집',state.tools.water&&'물가 제작',state.tools.pickaxe&&'광석 채집'].filter(Boolean).join(' · ')||'아직 없음';open('bag','가방',`<div class="callout">행복 Lv.${level} · 별 ${totalStars()}개${next!==undefined?` / 다음 Lv. ${next}개`:''}<br>기본 재화 ${state.coins}개 · 얻은 능력: ${abilities}</div><div class="inventory">${rows}</div><p class="muted">재료는 10~45초마다 다시 생깁니다. 행복 깃털은 친구의 부탁 보상으로 얻습니다.</p>`)}
function recipeRow(id,r){const locked=!craftUnlocked(id,r)||id==='stage'&&(state.residents.length<18||Object.values(state.unlocked).some(v=>!v));let time=state.job?.id===id?Math.max(0,Math.ceil((state.job.end-state.clock)/1000)):null;let available=enough(r.cost),stock=state.stock[id]||0;return `<div class="row"><span class="symbol">${r.icon||'⚒'}</span><div class="copy"><b>${r.name}${stock?` · 보관 ${stock}`:''}</b><small>${locked?`행복 Lv.${r.rep<=20?2:r.rep<=40?3:r.rep<=60?4:r.rep<=120?5:7}에 열림`:r.desc}</small><small>${costText(r.cost)} · ${durationText(r.time)}</small></div><button data-craft="${id}" ${locked||!available||state.job?'disabled':''}>${time!==null?remainingText(time):locked?'잠김':'만들기'}</button></div>`}
